package thaumcraft.world.eldritch;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.world.entity.*;
import net.minecraftforge.eventbus.api.IEventBus;
import net.minecraftforge.registries.*;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.network.*;
/** Registered BETA26 entities retain their IDs; no Outer Lands generator is invented. */
public final class EldritchModule {
 public static final DeferredRegister<EntityType<?>> TYPES=DeferredRegister.create(ForgeRegistries.ENTITY_TYPES,"thaumcraft");
 public static final DeferredRegister<Item> ITEMS=DeferredRegister.create(ForgeRegistries.ITEMS,"thaumcraft");
 private static final DeferredRegister<SoundEvent> SOUNDS=DeferredRegister.create(ForgeRegistries.SOUND_EVENTS,"thaumcraft");
 public static final RegistryObject<EntityType<InhabitedZombieEntity>> INHABITED_ZOMBIE=TYPES.register("inhabited_zombie",()->EntityType.Builder.<InhabitedZombieEntity>of(InhabitedZombieEntity::new,MobCategory.MONSTER).sized(.6F,1.95F).clientTrackingRange(4).updateInterval(3).build("thaumcraft:inhabited_zombie"));
 public static final RegistryObject<EntityType<thaumcraft.auromancy.remaining.FocusExchangeItemEntity>> SPECIAL_ITEM=TYPES.register("special_item",()->EntityType.Builder.<thaumcraft.auromancy.remaining.FocusExchangeItemEntity>of(thaumcraft.auromancy.remaining.FocusExchangeItemEntity::new,MobCategory.MISC).sized(.25F,.25F).clientTrackingRange(4).updateInterval(20).setShouldReceiveVelocityUpdates(true).build("thaumcraft:special_item"));
 private static final net.minecraftforge.network.simple.SimpleChannel NETWORK=NetworkRegistry.newSimpleChannel(id("eldritch_arcs"),()->"1","1"::equals,"1"::equals);
 public record Arc(ResourceLocation dimension,Vec3 source,Vec3 target,float red,float green,float blue,float height){}
 static{for(String name:java.util.List.of("crabtalk","crabdeath","crabclaw"))SOUNDS.register(name,()->SoundEvent.createVariableRangeEvent(ResourceLocation.fromNamespaceAndPath("thaumcraft",name)));ITEMS.register("inhabited_zombie_spawn_egg",()->new net.minecraftforge.common.ForgeSpawnEggItem(INHABITED_ZOMBIE,8421504,5570560,new Item.Properties()));}
 private EldritchModule(){}
 public static void register(IEventBus bus){TYPES.register(bus);ITEMS.register(bus);SOUNDS.register(bus);bus.addListener((net.minecraftforge.event.entity.EntityAttributeCreationEvent e)->e.put(INHABITED_ZOMBIE.get(),InhabitedZombieEntity.attributes().build()));NETWORK.registerMessage(0,Arc.class,(a,b)->{b.writeResourceLocation(a.dimension());b.writeDouble(a.source().x);b.writeDouble(a.source().y);b.writeDouble(a.source().z);b.writeDouble(a.target().x);b.writeDouble(a.target().y);b.writeDouble(a.target().z);b.writeFloat(a.red());b.writeFloat(a.green());b.writeFloat(a.blue());b.writeFloat(a.height());},b->new Arc(b.readResourceLocation(),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()),b.readFloat(),b.readFloat(),b.readFloat(),b.readFloat()),(a,c)->{var context=c.get();context.enqueueWork(()->net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->thaumcraft.world.eldritch.client.EldritchArcClient.receive(a)));context.setPacketHandled(true);},java.util.Optional.of(NetworkDirection.PLAY_TO_CLIENT));}
 public static ResourceLocation id(String name){return ResourceLocation.fromNamespaceAndPath("thaumcraft",name);}
 public static SoundEvent sound(String name){return ForgeRegistries.SOUND_EVENTS.getValue(ResourceLocation.fromNamespaceAndPath("thaumcraft",name));}
 /** Original entityDropSpecialItem, including Forge's physical captured-drop ownership. */
 public static thaumcraft.auromancy.remaining.FocusExchangeItemEntity specialDrop(Entity owner,ItemStack stack,float height){if(owner.level().isClientSide||stack.isEmpty())return null;var reward=SPECIAL_ITEM.get().create(owner.level());if(reward==null)return null;reward.setPos(owner.getX(),owner.getY()+height,owner.getZ());reward.setItem(stack);reward.setDefaultPickUpDelay();reward.setDeltaMovement(0,.10000000149011612,0);var capture=owner.captureDrops();if(capture!=null)capture.add(reward);else if(!owner.level().addFreshEntity(reward)){reward.discard();return null;}return reward;}
 public static net.minecraft.network.chat.Component championName(int type){String[] names={"bold","spine","armor","mighty","grim","warded","warp","undying","fiery","sickly","venomous","vampiric","infested","tainted"};return net.minecraft.network.chat.Component.translatable("champion.mod."+names[Math.floorMod(type,names.length)]);}
 public static void blockArc(Entity e,net.minecraft.core.BlockPos p,float r,float g,float b){arc(e,new Vec3((float)e.getX(),(float)(e.getY()+e.getBbHeight()/2),(float)e.getZ()),Vec3.atCenterOf(p),r,g,b,.5F);}
 public static void arc(Entity entity,Vec3 source,Vec3 target,float r,float g,float b,float height){Arc message=new Arc(entity.level().dimension().location(),source,target,r,g,b,height);if(entity.level().isClientSide)net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->thaumcraft.world.eldritch.client.EldritchArcClient.receive(message));else if(entity.level() instanceof net.minecraft.server.level.ServerLevel server)for(var p:server.players())if(p.connection!=null&&p.distanceToSqr(entity)<1024)NETWORK.send(PacketDistributor.PLAYER.with(()->p),message);}
 public static void spark(Entity entity,Vec3 position){var random=entity.level().random;var spec=new net.minecraft.nbt.CompoundTag();spec.putInt("life",5+random.nextInt(5));spec.putInt("grid",16);spec.putInt("start",8+random.nextInt(3)*16);spec.putInt("count",8);spec.putInt("inc",1);spec.putBoolean("flipped",random.nextBoolean());keys(spec,"rgb",.65F+random.nextFloat()*.1F,1,1);keys(spec,"alpha",.8F);keys(spec,"scale",3);thaumcraft.fx.FxDispatcher.generic(entity.level(),position,Vec3.ZERO,spec,0);}
 public static void cultistParticles(Entity entity){var random=entity.level().random;for(int i=0;i<20;i++){Vec3 velocity=new Vec3(random.nextGaussian()*.05,random.nextGaussian()*.05,random.nextGaussian()*.05);Vec3 point=entity.position().add(random.nextFloat()*entity.getBbWidth()*2-entity.getBbWidth()+velocity.x*2,random.nextFloat()*entity.getBbHeight()+velocity.y*2,random.nextFloat()*entity.getBbWidth()*2-entity.getBbWidth()+velocity.z*2);var spec=new net.minecraft.nbt.CompoundTag();spec.putInt("life",10+random.nextInt(10));spec.putInt("grid",16);spec.putInt("start",160);spec.putInt("count",6);spec.putInt("inc",1);spec.putInt("layer",1);keys(spec,"rgb",1,1,1);keys(spec,"rgbEnd",.6F,0,0);keys(spec,"alpha",.8F);keys(spec,"scale",3+random.nextFloat()*2);thaumcraft.fx.FxDispatcher.generic(entity.level(),point,velocity,spec,0);}}
 private static void keys(net.minecraft.nbt.CompoundTag tag,String name,float...values){var list=new net.minecraft.nbt.ListTag();for(float value:values)list.add(net.minecraft.nbt.FloatTag.valueOf(value));tag.put(name,list);}
}
